int main() {
    int n, m, a, b;
    if (!(cin >> n >> m >> a >> b)) return 0;

    // Option 1: all single tickets
    int cost_single = n * a;

    // Option 2: use m-ride tickets for full blocks, single for remainder
    int full_blocks = n / m;
    int remainder = n % m;
